SELECT Site.numsit,Intervention.refcliint,Site.nomsit,Site.typsit,Site.vilsit,Intervention.datint,Intervention.intfac,Intervention.codpan,Intervention.typint,Intervention.nummodres,Intervention.mntfac,Client.nomcli FROM [Client],[Site],[parametre],[Intervention] WHERE (((Intervention.datint) Between parametre!datdeb And parametre!datfin) And ((Intervention.intfac)=True)) ORDER BY Site.nomsit
